steps.cliCommand:
az group create \
  --name {{resourceGroup}} \
  --location {{region}}

cat << 'EOF' > template.json
{
  "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
  "contentVersion": "1.0.0.0",
  "parameters": {
    "storageName": { "type": "string" },
    "location": { "type": "string" }
  },
  "resources": [
    {
      "type": "Microsoft.Storage/storageAccounts",
      "apiVersion": "2022-09-01",
      "name": "[parameters('storageName')]",
      "location": "[parameters('location')]",
      "sku": { "name": "Standard_LRS" },
      "kind": "StorageV2",
      "properties": {
        "supportsHttpsTrafficOnly": true,
        "minimumTlsVersion": "TLS1_2"
      }
    }
  ]
}
EOF

SUB_ID=$(az account show --query id -o tsv)
echo "Current Subscription ID: $SUB_ID"

az group create --name {{resourceGroup}} --location {{region}}

az group create \
  --name {{resourceGroup}} \
  --location {{allowedRegion}}

steps.powershellCommand:
$nsg = New-AzNetworkSecurityGroup -ResourceGroupName '{{resourceGroup}}' -Location '{{region}}' -Name '{{nsgName}}'

$nsg | Add-AzNetworkSecurityRuleConfig -Name 'Allow_Web_{{webPort}}' -Access Allow -Protocol Tcp -Direction Inbound -Priority 200 -SourceAddressPrefix '*' -SourcePortRange '*' -DestinationAddressPrefix '*' -DestinationPortRange {{webPort}}
$nsg | Set-AzNetworkSecurityGroup

steps.cliCommand:
az network private-dns zone create \
  --name {{privateZoneName}} \
  --resource-group {{resourceGroup}}

cat << 'EOF' > lifecycle.json
{
  "rules": [
    {
      "enabled": true,
      "name": "CostOptimizationRule",
      "type": "Lifecycle",
      "definition": {
        "actions": {
          "baseBlob": {
            "tierToCool": { "daysAfterModificationGreaterThan": {{coolDays}} },
            "tierToArchive": { "daysAfterModificationGreaterThan": {{archiveDays}} }
          }
        },
        "filters": {
          "blobTypes": [ "blockBlob" ],
          "prefixMatch": [ "{{containerName}}/" ]
        }
      }
    }
  ]
}
EOF

az storage account management-policy create \
  --account-name {{storageAccount}} \
  --resource-group {{resourceGroup}} \
  --policy @lifecycle.json

steps.powershellCommand:
New-AzResourceGroup -Name '{{resourceGroup}}' -Location '{{region}}'
# VMSS creation via PowerShell or Azure CLI
az vmss show --name {{vmssName}} --resource-group {{resourceGroup}}

New-AzResourceGroup -Name '{{resourceGroup}}' -Location '{{region}}'
# Managed environment creation via Azure CLI / PowerShell
az containerapp env show --name {{acaEnvName}} --resource-group {{resourceGroup}}

New-AzResourceGroup -Name '{{resourceGroup}}' -Location '{{region}}'
# Provision AKS cluster via Azure CLI or PowerShell cmdlet
az aks show --name {{clusterName}} --resource-group {{resourceGroup}}

steps.cliCommand:
az group create --name {{resourceGroup}} --location {{region}}

az monitor log-analytics workspace create \
  --name {{workspaceName}} \
  --resource-group {{resourceGroup}} \
  --location {{region}} \
  --retention-time {{retentionDays}}

az group create --name {{resourceGroup}} --location {{region}}

az monitor action-group create \
  --name {{actionGroupName}} \
  --resource-group {{resourceGroup}} \
  --short-name {{shortName}} \
  --action email EmailAdmin {{emailAddress}}
